// Issue #200 CA-14, CA-15: the packaged desktop app, end to end. Two Projects
// generated by create_project through the built CLI (a platformer and a
// third-person demo) are exported with `waica export desktop` for this host's
// platform, and each binary is launched with playwright-core's _electron.
// The checks are logical state, never pixels: a runner without a GPU can draw
// a blank frame (issue #151). `--cross` also exports a platformer for all
// three platforms from this host and reads the Windows .exe's version
// resources, the macOS Info.plist and every resources/app tree. `--steam`
// exports one with Steam (a real npm install of steamworks.js) and launches it
// with no Steam client running: the game must still play, without achievements.
//
//   node scripts/runtime-e2e-desktop.mjs [--cross] [--steam]   (pnpm test:desktop builds first)
import assert from 'node:assert/strict'
import { spawn } from 'node:child_process'
import { existsSync } from 'node:fs'
import { cp, mkdir, mkdtemp, readFile, rm, symlink, writeFile } from 'node:fs/promises'
import { createRequire } from 'node:module'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..')
const cliPath = path.join(root, 'packages/cli/dist/cli.js')
const requireFromMcp = createRequire(path.join(root, 'packages/mcp/package.json'))
const requireFromCli = createRequire(path.join(root, 'packages/cli/package.json'))
const { Client } = requireFromMcp('@modelcontextprotocol/sdk/client/index.js')
const { StdioClientTransport } = requireFromMcp('@modelcontextprotocol/sdk/client/stdio.js')
const { _electron: electron } = requireFromMcp('playwright-core')

/** What each platform's export calls its folder and where its executable and resources/app sit in it. */
const LAYOUT = {
  linux: { arch: 'x64', executable: (name) => name, app: () => 'resources/app' },
  win32: { arch: 'x64', executable: (name) => `${name}.exe`, app: () => 'resources/app' },
  darwin: { arch: 'arm64', executable: (name) => `${name}.app/Contents/MacOS/${name}`, app: (name) => `${name}.app/Contents/Resources/app` },
}

/** A Project per archetype, each with a params override the packaged game must load through app://. */
const PROJECTS = [
  { archetype: 'platformer', params: { Player: { PlatformerMotor: { moveSpeed: 7.25 } } }, rapier: false },
  { archetype: 'third-person', params: { Player: { Health: { max: 9 } } }, rapier: true },
]

/** SwiftShader's WebGL2 (the engine's fallback, ADR 0025) on a Linux host without a GPU. */
const LINUX_GPU_SWITCHES = ['--use-angle=swiftshader', '--enable-unsafe-swiftshader']

function onPath(command) {
  return (process.env.PATH ?? '').split(path.delimiter).some((directory) => existsSync(path.join(directory, command)))
}

async function waitForFile(file, timeoutMs) {
  for (const deadline = Date.now() + timeoutMs; Date.now() < deadline; ) {
    if (existsSync(file)) return
    await new Promise((resolve) => setTimeout(resolve, 100))
  }
  throw new Error(`${file} did not appear within ${timeoutMs} ms`)
}

/** A private, virtual KWin compositor: a window manager that grants fullscreen, drawing nowhere. */
async function startVirtualCompositor() {
  const socket = `waica-desktop-e2e-${process.pid}`
  const env = { ...process.env, DISPLAY: '', WAYLAND_DISPLAY: '' }
  const kwin = spawn('kwin_wayland', ['--virtual', '--width', '1920', '--height', '1080', '--socket', socket, '--no-lockscreen'], { env, stdio: 'ignore' })
  await waitForFile(path.join(process.env.XDG_RUNTIME_DIR ?? '', socket), 15_000)
  const close = async () => {
    kwin.kill('SIGTERM')
    await new Promise((resolve) => (kwin.exitCode === null ? kwin.once('exit', resolve) : resolve()))
  }
  return { mode: 'kwin-virtual', env: { ...process.env, WAYLAND_DISPLAY: socket }, switches: ['--ozone-platform=wayland', ...LINUX_GPU_SWITCHES], close }
}

/**
 * Where the packaged window opens. A display the caller provides wins (CI's
 * xvfb-run). With none, a private virtual KWin when the host has one, since
 * headless Ozone cannot fullscreen a window; headless Ozone otherwise, where
 * the fullscreen check is expected to fail.
 */
async function openDisplay() {
  const none = async () => {}
  if (process.platform !== 'linux') return { mode: 'native', env: process.env, switches: [], close: none }
  if (process.env.DISPLAY || process.env.WAYLAND_DISPLAY) return { mode: 'provided', env: process.env, switches: LINUX_GPU_SWITCHES, close: none }
  if (onPath('kwin_wayland') && process.env.XDG_RUNTIME_DIR) return startVirtualCompositor()
  const headless = ['--ozone-platform=headless', '--ozone-override-screen-size=1920,1080', ...LINUX_GPU_SWITCHES]
  return { mode: 'headless', env: process.env, switches: headless, close: none }
}

async function findPackageRoot(entry, name) {
  for (let current = path.dirname(entry); current !== path.dirname(current); current = path.dirname(current)) {
    const manifest = path.join(current, 'package.json')
    if (existsSync(manifest) && JSON.parse(await readFile(manifest, 'utf8')).name === name) return current
  }
  throw new Error(`Cannot locate package root for ${name}`)
}

async function connectMcp() {
  const client = new Client({ name: 'waica-desktop-e2e', version: '1.0.0' })
  await client.connect(new StdioClientTransport({ command: process.execPath, args: [cliPath, 'mcp'], cwd: root, stderr: 'inherit' }), { timeout: 15_000 })
  return client
}

async function createProject(client, project, archetype) {
  const created = await client.callTool({ name: 'create_project', arguments: { project_path: project, start: 'demo', archetype } }, undefined, { timeout: 60_000 })
  assert.equal(created.isError, undefined, `create_project(${archetype}) failed: ${JSON.stringify(created)}`)
}

async function copyPackage(source, destination) {
  await mkdir(path.dirname(destination), { recursive: true })
  const nested = path.join(source, 'node_modules')
  await cp(source, destination, { recursive: true, dereference: true, filter: (file) => file !== nested && !file.startsWith(`${nested}${path.sep}`) })
}

/** What `npm install` would leave: the checkout's @waica packages, three, Rapier, and the editor's vite. */
async function installProject(project, archetype) {
  const modules = path.join(project, 'node_modules')
  for (const directory of ['engine', 'behaviors', `archetype-${archetype}`]) {
    await copyPackage(path.join(root, 'packages', directory), path.join(modules, '@waica', directory))
  }
  const requireFromEngine = createRequire(path.join(root, 'packages/engine/package.json'))
  for (const dependency of ['three', '@dimforge/rapier3d-deterministic-compat']) {
    await copyPackage(await findPackageRoot(requireFromEngine.resolve(dependency), dependency), path.join(modules, ...dependency.split('/')))
  }
  const requireFromEditor = createRequire(path.join(root, 'packages/editor/package.json'))
  // A junction on Windows, which needs no administrator rights; a plain directory symlink elsewhere.
  await symlink(await findPackageRoot(requireFromEditor.resolve('vite'), 'vite'), path.join(modules, 'vite'), process.platform === 'win32' ? 'junction' : 'dir')
}

/** The template keeps its Game local; this fixture hands it to the probes as the examples do in DEV. */
async function exposeGame(project) {
  const main = path.join(project, 'src/main.ts')
  const source = await readFile(main, 'utf8')
  const anchor = '  game.registerSceneCatalog({ scenes, registry })'
  assert.ok(source.includes(anchor), 'the template main.ts must register its scene catalog')
  await writeFile(main, source.replace(anchor, `  Object.assign(window, { __waica: { game } })\n${anchor}`))
}

function run(args, options = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [cliPath, ...args], { stdio: ['ignore', 'pipe', 'pipe'], ...options })
    let output = ''
    child.stdout.on('data', (chunk) => (output += chunk))
    child.stderr.on('data', (chunk) => (output += chunk))
    child.once('error', reject)
    child.once('exit', (code) => resolve({ code, output }))
  })
}

async function exportProject(project, platforms, { env = process.env, flags = [] } = {}) {
  const exported = await run(['export', 'desktop', project, '--platform', platforms.join(','), ...flags], { env })
  assert.equal(exported.code, 0, `waica export desktop failed:\n${exported.output}`)
  return exported.output
}

async function makeProject(client, parent, spec) {
  const project = path.join(parent, `${spec.label ?? spec.archetype}-desktop`)
  await createProject(client, project, spec.archetype)
  await installProject(project, spec.archetype)
  await exposeGame(project)
  await writeFile(path.join(project, 'public/waica.params.json'), `${JSON.stringify(spec.params)}\n`)
  return { project, name: JSON.parse(await readFile(path.join(project, 'package.json'), 'utf8')).name }
}

function exportedFolder(project, name, platform) {
  return path.join(project, 'export', `${name}-${platform}-${LAYOUT[platform].arch}`)
}

/** The params override, read back from the live Game: proof waica.params.json came through app://. */
function paramState(page, params) {
  return page.evaluate((expected) => {
    const { game } = globalThis.__waica
    const [[entity, byComponent]] = Object.entries(expected)
    const [[componentName, props]] = Object.entries(byComponent)
    const [[prop]] = Object.entries(props)
    const component = game.find(entity)?.components.find((candidate) => candidate.constructor.componentName === componentName)
    return { overrides: game.paramOverrides, value: component?.[prop] }
  }, params)
}

async function assertPlays(page, spec) {
  await page.waitForFunction(() => globalThis.__waica !== undefined, null, { timeout: 30_000 })
  const from = await page.evaluate(() => globalThis.__waica.game.time.now)
  await page.waitForFunction((since) => globalThis.__waica.game.time.now > since + 0.2, from, { timeout: 30_000 })
  const to = await page.evaluate(() => globalThis.__waica.game.time.now)
  const params = await paramState(page, spec.params)
  assert.deepEqual(params.overrides, spec.params, 'the packaged game must load public/waica.params.json through app://')
  assert.equal(params.value, Object.values(Object.values(Object.values(spec.params)[0])[0])[0], 'the override must reach the component')
  if (spec.rapier) await page.waitForFunction(() => globalThis.__waica.game.physics.state === 'ready', null, { timeout: 30_000 })
  const physics = await page.evaluate(() => globalThis.__waica.game.physics.state)
  return { gameTime: { from, to }, params: params.value, physics: spec.rapier ? physics : 'n/a (2D)' }
}

async function assertPlatform(page) {
  const platform = await page.evaluate(async () => {
    const { game } = globalThis.__waica
    const before = game.isFullscreen()
    await game.setFullscreen(true)
    return { canQuit: game.canQuit, before, after: game.isFullscreen(), achievements: game.achievements.available }
  })
  if (!platform.after) {
    // Tells a slow transition (true a little later) apart from a window that never goes fullscreen.
    const later = await page.waitForFunction(() => globalThis.__waica.game.isFullscreen(), null, { timeout: 10_000 }).then(() => true, () => false)
    assert.fail(`setFullscreen(true) resolved with isFullscreen() false; 10 s later it was ${later}`)
  }
  assert.deepEqual(platform, { canQuit: true, before: false, after: true, achievements: false })
  return platform
}

async function assertQuits(app, page) {
  const exited = new Promise((resolve) => app.process().once('exit', (code, signal) => resolve({ code, signal })))
  await page.evaluate(() => setTimeout(() => globalThis.__waica.game.quit(), 50))
  const outcome = await exited
  assert.deepEqual(outcome, { code: 0, signal: null }, 'game.quit() must end the app with code 0')
  return outcome
}

/** Exports one Project for this host and launches its binary; `flags` go to the export. */
async function launchExport({ client, parent, display }, spec, flags = []) {
  const { project, name } = await makeProject(client, parent, spec)
  await exportProject(project, [process.platform], { flags })
  const folder = exportedFolder(project, name, process.platform)
  const app = await electron.launch({ executablePath: path.join(folder, LAYOUT[process.platform].executable(name)), args: display.switches, env: display.env, timeout: 60_000 })
  return { app, folder, name }
}

/** Runs `checks` on a launched app's window, closing the app if one fails. */
async function withWindow(app, checks) {
  try {
    return await checks(await app.firstWindow())
  } catch (error) {
    await app.close().catch(() => {})
    throw error
  }
}

/** Every CA-15 check on one Project exported for this host. */
async function smokeProject(context, spec) {
  const { app } = await launchExport(context, spec)
  return withWindow(app, async (page) => {
    const plays = await assertPlays(page, spec)
    if (process.platform === 'darwin') {
      const diag = await app.evaluate(async ({ app: electronApp, BrowserWindow }) => {
        const w = BrowserWindow.getAllWindows()[0]
        const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
        const state = () => ({ fs: w.isFullScreen(), simple: w.isSimpleFullScreen(), focused: w.isFocused(), visible: w.isVisible(), fsable: w.isFullScreenable(), normal: w.isNormal(), bounds: w.getBounds() })
        const out = { start: state() }
        w.setFullScreen(true)
        await wait(3000)
        out.plain = state()
        w.setFullScreen(false)
        await wait(1500)
        electronApp.focus({ steal: true })
        w.show()
        w.focus()
        await wait(500)
        out.focusedBefore = state()
        w.setFullScreen(true)
        await wait(3000)
        out.afterFocus = state()
        w.setFullScreen(false)
        await wait(1500)
        w.setSimpleFullScreen(true)
        await wait(1000)
        out.simple = state()
        w.setSimpleFullScreen(false)
        await wait(500)
        out.end = state()
        return out
      })
      console.log('[DEBUG-fs]', JSON.stringify(diag))
    }
    const platform = await assertPlatform(page)
    return { archetype: spec.archetype, ...plays, ...platform, quit: await assertQuits(app, page) }
  })
}

/** CA-16, CA-17 with the real modules: steamworks.js installed by npm, and no Steam client, so init fails and the game plays on. */
async function steamLeg(context) {
  const spec = { ...PROJECTS[0], label: 'steam' }
  const { app, folder, name } = await launchExport(context, spec, ['--steam-app-id', '480'])
  const resources = path.join(folder, LAYOUT[process.platform].app(name))
  const steamworks = JSON.parse(await readFile(path.join(resources, 'node_modules/steamworks.js/package.json'), 'utf8')).version
  assert.equal(steamworks, '0.4.0', 'the export must install steamworks.js 0.4.0')
  assert.equal(await readFile(path.join(resources, 'steam_appid.txt'), 'utf8'), '480')
  return withWindow(app, async (page) => {
    await assertPlays(page, spec)
    const available = await page.evaluate(() => globalThis.__waica.game.achievements.available)
    assert.equal(available, false, 'without a Steam client the achievements must be unavailable')
    return { steamworks, available, quit: await assertQuits(app, page) }
  })
}

/** The PE's version strings and icon groups, read with the same resedit @electron/packager writes them with. */
async function exeResources(exe) {
  const requireFromPackager = createRequire(requireFromCli.resolve('@electron/packager'))
  const ResEdit = await import(pathToFileURL(requireFromPackager.resolve('resedit')).href)
  const { entries } = ResEdit.NtExecutableResource.from(ResEdit.NtExecutable.from(await readFile(exe)))
  const [info] = ResEdit.Resource.VersionInfo.fromEntries(entries)
  const [language] = info.getAllLanguagesForStringValues()
  return { strings: info.getStringValues(language), iconGroups: ResEdit.Resource.IconGroupEntry.fromEntries(entries).length }
}

async function plistValues(file) {
  const requireFromPackager = createRequire(requireFromCli.resolve('@electron/packager'))
  const { default: plist } = await import(pathToFileURL(requireFromPackager.resolve('plist')).href)
  return plist.parse(await readFile(file, 'utf8'))
}

function assertResourcesApp(folder, platform, name) {
  const app = path.join(folder, LAYOUT[platform].app(name))
  for (const file of ['dist/index.html', 'main.js', 'preload.js', 'waica-desktop.json']) {
    assert.ok(existsSync(path.join(app, file)), `${platform}: resources/app must hold ${file}`)
  }
}

/** CA-14: a fresh platformer exported for all three platforms from this host, with no wine on PATH (CA-13). */
async function crossLeg(client, parent) {
  const { project, name } = await makeProject(client, parent, { ...PROJECTS[0], label: 'cross' })
  const env = { ...process.env, PATH: path.dirname(process.execPath) }
  const output = await exportProject(project, ['linux', 'win32', 'darwin'], { env })
  assert.doesNotMatch(output, /wine/i, 'the export never needs wine')
  for (const platform of ['linux', 'win32', 'darwin']) {
    const folder = exportedFolder(project, name, platform)
    assert.ok(existsSync(`${folder}.zip`), `${platform}: the export must write ${folder}.zip`)
    assertResourcesApp(folder, platform, name)
  }
  const { strings, iconGroups } = await exeResources(path.join(exportedFolder(project, name, 'win32'), `${name}.exe`))
  assert.equal(strings.ProductName, name, 'the .exe version resources must carry the app name')
  assert.ok(iconGroups > 0, 'the .exe must carry an icon')
  const info = await plistValues(path.join(exportedFolder(project, name, 'darwin'), `${name}.app/Contents/Info.plist`))
  assert.equal(info.CFBundleName, name, 'the .app Info.plist must carry the app name')
  return { name, exe: { ProductName: strings.ProductName, FileDescription: strings.FileDescription, iconGroups }, plist: { CFBundleName: info.CFBundleName } }
}

async function main() {
  assert.ok(existsSync(cliPath), `missing ${cliPath}: run pnpm build first (pnpm test:desktop does)`)
  const startedAt = Date.now()
  const parent = await mkdtemp(path.join(tmpdir(), 'waica-desktop-e2e-'))
  const client = await connectMcp()
  const display = await openDisplay()
  try {
    const smoke = []
    for (const spec of PROJECTS) smoke.push(await smokeProject({ client, parent, display }, spec))
    const cross = process.argv.includes('--cross') ? await crossLeg(client, parent) : null
    const steam = process.argv.includes('--steam') ? await steamLeg({ client, parent, display }) : null
    const report = { platform: process.platform, display: display.mode, switches: display.switches, smoke, cross, steam, durationMs: Date.now() - startedAt }
    console.log(`waica desktop e2e: ${JSON.stringify(report)}`)
  } finally {
    await display.close()
    await client.close()
    await rm(parent, { recursive: true, force: true })
  }
}

await main()
